var cw, ch
var palette = {
  BACKGROUND: "#739C9E",
  LAND: ["#4b8a5f", "#025760", "#4d8c8c"],
  ROCK: ["#283037", "#32312e", "#2A3331", "#44473f"],
  TREES: ["#10100f", "#BF984E", "#4b8a5f", "#025760", "#4d8c8c", "#30735A"],
  BG_GRADIENT: [
    "#1B1D22",
    "#435054",
    "#739C9E",
    "#b3dce0",
    "#F7975B",
    "#EB5926",
    "#BF1906",
  ],
}
var islands, clouds
var texture

function setup() {
  ch = windowHeight
  cw = min(windowWidth, (windowHeight * 3) / 4)
  background(palette.BACKGROUND)
  createCanvas(cw, ch)
  angleModetexture = texturize(80)
  regenerate()
}

function draw() {
  background(palette.BACKGROUND)
  let g = drawingContext.createLinearGradient(0, 0, 0, ch)

  for (let i = 0; i < palette.BG_GRADIENT.length; i++) {
    g.addColorStop(ease(i / palette.BG_GRADIENT.length), palette.BG_GRADIENT[i])
  }
  drawingContext.fillStyle = g
  rect(0, 0, cw, ch)
  let cloudsPerIsland = clouds.length / (islands.length + 1)
  for (let i = 0; i <= islands.length; i++) {
    for (
      let j = floor(cloudsPerIsland * i);
      j < floor(cloudsPerIsland * (i + 1));
      j++
    ) {
      let c = clouds[j]
      push()
      translate(c.x - c.w / 2, c.y - c.h / 2)
      tint(255, c.alpha)
      image(c.img, 0, 0, c.w, c.h)
      pop()
    }
    if (i < islands.length) {
      let island = islands[i]
      push()
      translate(island.x, island.y)
      island.draw()
      pop()
    }
  }
  for (let i of islands) {
  }
  blendModeimage(texture, 0, 0, cw, ch)
  blendMode(BLEND)
}

var regenerate = () => {
  seedIslands()
  seedClouds()
}

var seedClouds = () => {
  clouds = []
  for (let i = 0; i < 10; i++) {
    let w = random(cw / 3, (2 * cw) / 3)
    let h = w * random(0.2, 0.4)
    let cloud = createCloud(w, h)
    for (let n = 0; n < 5; n++) {
      clouds.push({
        x: random(cw),
        y: random(ch / 5, ch * 4 / 5),
        w,
        h,
        img: cloud.img,
        alpha: random(20, 80),
      })
    }
  }
}

var createCloud = (w, h) => {
  let _cloud = createGraphics(w, h)
  for (let j = 0; j < 5; j++) {
    let y0 = (j * h) / 8
    let n
    for (let i = 0; i < w; i += n / 2) {
      let f = abs(w / 2 - i)
      let s = map(f, w / 2, 0, 1, 2)
      n = s ** 1.1 * random(h / 8, h / 4) * 1 ** y0
      let y = h + y0 - random(-n / 4, n / 2) - (n / 2) * map(f, w / 2, 0, 0, 2)
      if (i > n / 2 && i < w - n / 2) {
        let a = -135
        let ni = i + n * (4 / 5) * cos(a)
        let ny = y + n * (4 / 5) * sin(a)
        let mi = i + n * cos(180 + a)
        let my = y + n * sin(180 + a)
        let g = _cloud.drawingContext.createRadialGradient(
          ni,
          ny,
          0,
          mi,
          my,
          n * 1.2
        )
        // g.addColorStop(0, '#FFFFFF20')
        let color1 = withAlpha("#FFF", 80)
        g.addColorStop(0, "#b3dce0AA")
        g.addColorStop(0.2, "#b3dce0CC")
        g.addColorStop(1, "#e2f0f3FF")

        // _cloud.blendMode_cloud.noStroke()
        _cloud.drawingContext.fillStyle = g
        _cloud.circle(i, y, n)
      }
    }
  }
  return {
    w,
    h,
    img: _cloud,
  }
}

var seedIslands = () => {
  islands = []
  let numIslands = floor(random(3, 8))
  for (let i = 0; i < numIslands; i++) {
    let w = random(300, 500)
    islands.push(
      new Island({
        width: w,
        height: w * random(0.2, 0.25),
        numTrees: random(10, 30),
        x: map(noise(frameCount + i * 5), 0, 1, w / 3, cw - w / 3),
        y: map(i+1, 0, numIslands, ch / 6, ch * 5 / 6),
      })
    )
  }
}

function mouseClicked() {
  regenerate()
}

class Island {
  constructor({ width, height, x, y, numTrees }) {
    // Use half width internally
    this.width = width / 2
    this.height = height / 2
    this.x = x
    this.y = y

    this.numTrees = numTrees
    this.treeConfig = {
      minHeightFactor: random(0.5, 1),
      maxHeightFactor: random(2, 3.5),
      maxAreaFactor: random(1 / 2, 7 / 10),
    }
    this.surfaceConfig = {
      minNoise: 0.8,
      maxNoise: 1.2,
      noiseScale: 3,
      noiseSpeed: 0.005,
      emptySpace: this.height / random(6, 10),
      color: random(palette.LAND),
    }
    this.islandConfig = {
      minHeight: this.height * random(0.25, 0.5),
      maxHeight: this.height * random(1.5, 2.5),
      maxNoise: 1.2,
      curveFactor: random(0.6, 0.7),
      heightFactor: random(1.5, 2),
      color: random(palette.ROCK),
    }

    this.seedTrees()
  }

  scale(factor) {
    this.width *= factor
    this.height *= factor
    this.treeConfig.minHeight *= factor
    this.treeConfig.maxHeight *= factor
    this.islandConfig.minHeight *= factor
    this.islandConfig.maxHeight *= factor
  }

  seedTrees() {
    this.trees = []
    for (let i = 0; i < this.numTrees; i++) {
      let hF = random(
        this.treeConfig.minHeightFactor,
        this.treeConfig.maxHeightFactor
      )
      let tree = {
        xF: random(
          -this.treeConfig.maxAreaFactor,
          this.treeConfig.maxAreaFactor
        ),
        yF: 0,
        hF,
        wF: 1 / random(2, 3),
        color: random(palette.TREES),
      }
      let strokeColor = random(palette.TREES)
      while (strokeColor === tree.color) {
        strokeColor = random(palette.TREES)
      }
      tree.strokeColor = withAlpha(strokeColor, 250)
      tree.color = withAlpha(tree.color, 140)
      this.trees.push(tree)
    }
  }

  generateSurface() {
    let points = []
    for (let angle = 0; angle < 360; angle += 2) {
      let f = frameCount * this.surfaceConfig.noiseSpeed
      let n = map(
        noise(
          f + sin(angle) * this.surfaceConfig.noiseScale,
          f + cos(angle) * this.surfaceConfig.noiseScale
        ),
        0,
        1,
        this.surfaceConfig.minNoise,
        this.surfaceConfig.maxNoise
      )
      let x = this.width * n * cos(angle)
      let y = this.height * n * sin(angle)
      points.push([x, y])
    }
    return points
  }

  draw() {
    let points = this.generateSurface()
    this.drawIsland(points)
    this.drawSurface(points)
    this.drawTrees()
  }

  drawSurface(points) {
    erase()
    poly(points)
    poly(points, 0, this.surfaceConfig.emptySpace)
    noErase()

    noStroke()
    fill(palette.BACKGROUND)
    poly(points)
    poly(points, 0, this.surfaceConfig.emptySpace * 2)

    fill(withAlpha(this.surfaceConfig.color, 200))
    poly(points, 0, this.surfaceConfig.emptySpace)

    fill(withAlpha(this.surfaceConfig.color, 80))
    strokeWeight(this.height / 4)
    strokeCapstroke(0, 0, 0, 30)
    poly(points)
  }

  drawIsland(points) {
    let iPoints = []
    let minX = Infinity,
      maxX = -Infinity
    let minYLeft, minYRight
    for (let p of points) {
      if (p[0] < minX) {
        minX = p[0]
        minYLeft = p[1]
      }
      if (p[0] > maxX) {
        maxX = p[0]
        minYRight = p[1]
      }
    }
    for (let i = 0; i < points.length; i++) {
      let p1 = points[i]
      if (
        (p1[0] < 0 && p1[1] > minYLeft) ||
        (p1[0] >= 0 && p1[1] > minYRight)
      ) {
        let x = this.width * this.islandConfig.maxNoise
        let y =
          this.islandConfig.minHeight +
          parabolaMapping(
            p1[0],
            -x,
            x,
            this.islandConfig.maxHeight,
            this.islandConfig.curveFactor
          ) *
            map(
              noise((p1[0] + p1[1]) * 0.05),
              0,
              1,
              1,
              this.islandConfig.heightFactor
            )
        iPoints.push([p1[0], p1[1] + max(y, 0)])
        // rect(
        //   points[i][0], points[i][1],
        //   max(abs(points[i][0] - points[(i+2) % points.length][0]), 10),
        //   y
        // )
      } else {
        iPoints.push(p1)
      }
    }
    fill(this.islandConfig.color)
    noStroke()
    poly(iPoints)
  }

  drawTrees() {
    for (let tree of this.trees) {
      let h = tree.hF * this.height
      let w = h * tree.wF
      let x = tree.xF * this.width
      let y = tree.yF * this.height
      noStroke()
      let t = drawingContext.createLinearGradient(
        x - w / 2,
        y - h,
        x + w / 2,
        h
      )
      t.addColorStop(1, tree.color)
      t.addColorStop(0, tree.strokeColor)
      drawingContext.fillStyle = t
      let s = 0.05
      rect(
        x - w / 2,
        y - h,
        w,
        h,
        w / map(noise(x, y, frameCount * s), 0, 1, 2, 4),
        w / map(noise(x, y, frameCount * s), 0, 1, 2, 4),
        0,
        0
      )
    }
  }
}

//-------------------------------------
//-------- Auxiliary functions --------
//-------------------------------------

var poly = (points, deltaX = 0, deltaY = 0) => {
  beginShape()
  for (let p of points) {
    vertex(p[0] + deltaX, p[1] + deltaY)
  }
  endShape(CLOSE)
}

var parabolaMapping = (x, rangeStart, rangeEnd, fixedY, factor) => {
  const midPoint = (rangeStart + rangeEnd) / 2
  const range = (rangeEnd - rangeStart) / 2
  const tx = abs(midPoint - x)
  const y = map(tx, 0, range, 0, sqrt(fixedY) / factor)
  return fixedY - y ** 2 * factor
}

var ease = (x) => {
  return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2
}

var withAlpha = (c, alpha) => {
  let newColor = color(c)
  newColor.setAlpha(alpha)
  return newColor
}

var texturize = (gA) => {
  let gc = createGraphics(cw, cw)
  gc.loadPixels()
  let d = gc.pixelDensity()
  let halfImage = 4 * (cw * d) * (cw * d)
  for (let ii = 0; ii < halfImage; ii += 4) {
    // noprotect
    grainAmount = map(noise(ii * 0.005), 0, 1, -gA, gA)
    gc.pixels[ii] = gc.pixels[ii] + grainAmount // R
    gc.pixels[ii + 1] = gc.pixels[ii + 1] + grainAmount * 1.2 // G
    gc.pixels[ii + 2] = gc.pixels[ii + 2] + grainAmount * 2 // B
    gc.pixels[ii + 3] = gc.pixels[ii + 3] + grainAmount / 2 // Alpha
  }
  gc.updatePixels()
  return gc
}


